# King's Bible Quest question bank, part 1 (Old Testament).
# Each entry: (difficulty, question, [right, wrong, wrong, wrong], explanation with reference)
# K = kids (ages 5-12), A = grown-ups. Verse quotes are from the King James Version.
LANDS = []

def land(id, name, blurb, kids, adults):
    LANDS.append(dict(id=id, name=name, blurb=blurb, kids=kids, adults=adults))

